exec('import csv,os,requests\nrows=list(csv.DictReader(open("signals_history.csv",encoding="utf-8")))\neligible=[r for r in rows if r["signal"] in ("ACHAT","SURCHAUFFE")]\nlatest=max(r["date"] for r in eligible)\nselected=[r for r in eligible if r["date"]==latest]\nlines=["INVESTMENT ASSISTANT",f"Derniere date avec signal : {latest}",""]\nfor r in selected: lines.append(r["signal"]+" | "+r["ticker"]+" | Cloture J-1 : "+r["price"]+" | Score "+r["score"]+"/100 | Var5j "+r["var5"]+"% | RSI "+r["rsi14"]+" | RVOL "+r["rvol"])\nlines.extend(["","Message de verification. Signaux experimentaux en paper trading. Aucun ordre reel."])\nmessage="\\n".join(lines)\nr=requests.post("https://api.telegram.org/bot"+os.environ["TELEGRAM_BOT_TOKEN"]+"/sendMessage",data={"chat_id":os.environ["TELEGRAM_CHAT_ID"],"text":message},timeout=30)\nprint("Telegram alert:",r.status_code,r.json().get("ok"))')
